export const HALL = {
  cz: -18.5,        // centro de la estancia (pared frontal de la cancha: z -5,55)
  hx: 3.4,          // semiancho
  depth: 7,         // fondo (z -22 … -15)
  h: 2.85,          // mismo techo que la sala
};
/* DEPS-FASE2-INICIO (generado por scripts/mod_fase2_generar.mjs — no editar a mano) */
import { T, TLang } from './c00_pre_three.js';
import { DIMS } from './c02_cfg_escena.js';
import * as THREE from 'three';
/* DEPS-FASE2-FIN */
/* paleta de pieles en el orden de SKINS (la lista vive en el módulo de
 * entrenamiento: colores repetidos aquí a propósito, son estáticos) */
export const HALL_SKIN_IDS = ['clasica', 'fuego', 'hielo', 'oro', 'arcoiris', 'carbon'];
export const HALL_SKIN_COLS = ['#8a6a4a', '#ff5a2a', '#35c4e8', '#f2c14e', '#b07aff', '#ff2d2d'];

function hallCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}

export function drawHallSign(cv, title) {
  const x = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  const g = x.createLinearGradient(0, 0, W, H);
  g.addColorStop(0, '#241a12'); g.addColorStop(1, '#160f0a');
  x.fillStyle = g;
  x.fillRect(0, 0, W, H);
  x.strokeStyle = '#c9932f'; x.lineWidth = 6;
  x.strokeRect(6, 6, W - 12, H - 12);
  x.fillStyle = '#ffd257';
  // el título SIEMPRE cabe: se encoge hasta caber con margen
  let size = 92;
  x.font = '900 ' + size + 'px system-ui, sans-serif';
  while (x.measureText(title).width > W - 84 && size > 36) {
    size -= 4;
    x.font = '900 ' + size + 'px system-ui, sans-serif';
  }
  x.textAlign = 'center'; x.textBaseline = 'middle';
  x.shadowColor = 'rgba(0,0,0,.6)'; x.shadowBlur = 10;
  x.fillText(title, W / 2, H / 2 + 4);
  x.shadowBlur = 0;
}

export function drawHallDoor(cv, label) {
  const x = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  x.clearRect(0, 0, W, H);
  x.fillStyle = 'rgba(12,9,6,0.88)';
  x.fillRect(0, 0, W, H);
  x.strokeStyle = '#8d6a33'; x.lineWidth = 5;
  x.strokeRect(6, 6, W - 12, H - 12);
  x.fillStyle = '#e9c877';
  x.font = '700 74px system-ui, sans-serif';
  x.textAlign = 'center'; x.textBaseline = 'middle';
  x.fillText(label, W / 2, H / 2 + 2);
}

/* Lienzo de LOGROS CRAZY: 6 medalliones (emoji + nombre) — dorado y
 * encendido si está conseguido, apagado si falta: la pared invita. */
export function drawHallAchs(cv, items) {
  const x = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  x.clearRect(0, 0, W, H);
  const n = Math.max(items.length, 1);
  const cell = W / n;
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    const cx = cell * i + cell / 2, cy = H / 2;
    const on = !!it.on;
    x.beginPath();
    x.arc(cx, cy, 74, 0, Math.PI * 2);
    x.fillStyle = on ? 'rgba(58,42,14,0.95)' : 'rgba(20,22,26,0.9)';
    x.fill();
    x.lineWidth = 8;
    x.strokeStyle = on ? '#e9b83c' : '#3a4048';
    x.stroke();
    if (on) {
      x.beginPath();
      x.arc(cx, cy, 88, 0, Math.PI * 2);
      x.strokeStyle = 'rgba(233,184,60,0.35)';
      x.lineWidth = 4;
      x.stroke();
    }
    x.textAlign = 'center'; x.textBaseline = 'middle';
    x.globalAlpha = on ? 1 : 0.35;
    x.font = '58px system-ui, sans-serif';
    x.fillText(it.emoji || '★', cx, cy - 30);
    x.font = '700 30px system-ui, sans-serif';
    x.fillStyle = on ? '#ffe9a8' : '#5d6570';
    const words = String(it.name || '').toUpperCase().split(' ');
    const l1 = words.slice(0, Math.ceil(words.length / 2)).join(' ');
    const l2 = words.slice(Math.ceil(words.length / 2)).join(' ');
    x.fillText(l1, cx, cy + 18);
    if (l2) x.fillText(l2, cx, cy + 50);
    x.globalAlpha = 1;
  }
}

/* Lienzo PRO CIRCUITO + PIEL DE PALA: dos placas de madera con números
 * grandes y los colores de las pieles conseguidas. */
export function drawHallCirc(cv, circ, palas) {
  const x = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  x.clearRect(0, 0, W, H);
  const half = W / 2;
  const plate = (x0, title, big, sub, dots) => {
    x.fillStyle = 'rgba(24,17,11,0.92)';
    x.fillRect(x0 + 8, 8, half - 16, H - 16);
    x.strokeStyle = '#6e5324'; x.lineWidth = 5;
    x.strokeRect(x0 + 8, 8, half - 16, H - 16);
    x.textAlign = 'center';
    x.fillStyle = '#c9932f';
    x.font = '700 40px system-ui, sans-serif';
    x.textBaseline = 'alphabetic';
    x.fillText(title, x0 + half / 2, 62);
    x.fillStyle = '#ffd257';
    x.font = '900 84px system-ui, sans-serif';
    x.fillText(big, x0 + half / 2, 156);
    if (dots && dots.length) {
      const n = dots.length;
      for (let i = 0; i < n; i++) {
        x.beginPath();
        x.arc(x0 + half / 2 + (i - (n - 1) / 2) * 62, 202, 20, 0, Math.PI * 2);
        x.fillStyle = dots[i].c;
        x.globalAlpha = dots[i].on ? 1 : 0.2;
        x.fill();
        x.globalAlpha = 1;
      }
    } else if (sub) {
      x.fillStyle = '#b9a77f';
      x.font = '600 34px system-ui, sans-serif';
      x.fillText(sub, x0 + half / 2, 208);
    }
  };
  plate(0, circ.title, circ.big, circ.sub, null);
  plate(half, palas.title, palas.big, '', palas.dots);
}

export function createHall() {
  const g = new THREE.Group();
  const W = HALL.hx * 2;
  const z0 = HALL.cz - HALL.depth / 2;   // pared de los trofeos
  const z1 = HALL.cz + HALL.depth / 2;   // pared de la puerta

  const wallMat = new THREE.MeshStandardMaterial({ color: 0x43352d, roughness: 1 });
  const woodMat = new THREE.MeshStandardMaterial({ color: 0x8a5a33, roughness: 0.9 });
  const woodDark = new THREE.MeshStandardMaterial({ color: 0x55381f, roughness: 0.9 });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(W, HALL.depth),
    new THREE.MeshStandardMaterial({ color: 0x9a6a3c, roughness: 0.94 }));
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(0, 0.001, HALL.cz);
  g.add(floor);
  const rug = new THREE.Mesh(new THREE.PlaneGeometry(2.7, 1.8),
    new THREE.MeshStandardMaterial({ color: 0x7a2230, roughness: 1 }));
  rug.rotation.x = -Math.PI / 2;
  rug.position.set(0, 0.012, HALL.cz + 1.2);
  g.add(rug);

  const wall = (w, h, x, y, z, ry) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), wallMat);
    m.position.set(x, y, z);
    m.rotation.y = ry;
    g.add(m);
    return m;
  };
  wall(HALL.depth, HALL.h, -HALL.hx, HALL.h / 2, HALL.cz, Math.PI / 2);
  wall(HALL.depth, HALL.h, HALL.hx, HALL.h / 2, HALL.cz, -Math.PI / 2);
  wall(W, HALL.h, 0, HALL.h / 2, z0, 0);
  wall(W, HALL.h, 0, HALL.h / 2, z1, Math.PI);
  const ceil = new THREE.Mesh(new THREE.PlaneGeometry(W, HALL.depth),
    new THREE.MeshStandardMaterial({ color: 0x2a201c, roughness: 1 }));
  ceil.rotation.x = Math.PI / 2;
  ceil.position.set(0, HALL.h, HALL.cz);
  g.add(ceil);

  // lámparas cálidas propias (la cancha queda apagada detrás)
  const lampMat = new THREE.MeshStandardMaterial({
    color: 0xfff2cf, emissive: 0xffd9a0, emissiveIntensity: 1.7, roughness: 0.4 });
  const lights = [];
  for (const lx of [-1.7, 1.7]) {
    const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.09, 12, 10), lampMat);
    lamp.position.set(lx, HALL.h - 0.32, HALL.cz);
    g.add(lamp);
    const pl = new THREE.PointLight(0xffd9a0, 0.9, 8, 1.5);
    pl.position.set(lx, HALL.h - 0.45, HALL.cz);
    g.add(pl);
    lights.push(pl);
  }

  // peana con la bola de exhibición del anfitrión
  const ped = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.17, 0.9, 20), woodDark);
  ped.position.set(-2.2, 0.45, HALL.cz + 0.7);
  g.add(ped);
  const pedBall = new THREE.Mesh(new THREE.SphereGeometry(0.02, 16, 12),
    new THREE.MeshStandardMaterial({ color: 0xfff6e8, roughness: 0.35 }));
  pedBall.position.set(-2.2, 0.93, HALL.cz + 0.7);
  g.add(pedBall);

  const mkTex = (cv) => {
    const t = new THREE.CanvasTexture(cv);
    t.anisotropy = 4;
    return t;
  };
  const signCv = hallCanvas(1024, 256);
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.5, 0.62),
    new THREE.MeshBasicMaterial({ map: mkTex(signCv), transparent: true }));
  sign.position.set(0, 2.38, z0 + 0.04);
  g.add(sign);

  for (const sy of [1.95, 1.5, 1.05]) {
    const shelf = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.04, 0.16), woodMat);
    shelf.position.set(0, sy - 0.26, z0 + 0.09);
    g.add(shelf);
  }

  // fila CAMPEONATOS: los marcos los monta drawHall() según las entradas
  // cargadas (el catálogo llega async: la fila se reconstruye sola)
  const champRow = new THREE.Group();
  champRow.position.set(0, 0, z0 + 0.05);
  champRow.userData.n = -1;
  champRow.userData.slots = [];
  g.add(champRow);

  const achsCv = hallCanvas(2048, 256);
  const achsRow = new THREE.Mesh(new THREE.PlaneGeometry(3.3, 0.42),
    new THREE.MeshBasicMaterial({ map: mkTex(achsCv), transparent: true }));
  achsRow.position.set(0, 1.5, z0 + 0.04);
  g.add(achsRow);

  const circCv = hallCanvas(2048, 256);
  const circRow = new THREE.Mesh(new THREE.PlaneGeometry(3.3, 0.42),
    new THREE.MeshBasicMaterial({ map: mkTex(circCv), transparent: true }));
  circRow.position.set(0, 1.05, z0 + 0.04);
  g.add(circRow);

  const doorCv = hallCanvas(1024, 256);
  const door = new THREE.Mesh(new THREE.PlaneGeometry(1.7, 0.42),
    new THREE.MeshBasicMaterial({ map: mkTex(doorCv), transparent: true }));
  door.position.set(0, 1.72, z1 - 0.04);
  door.rotation.y = Math.PI;
  g.add(door);

  g.userData.hall = {
    signCv, achsCv, circCv, doorCv,
    signTex: sign.material.map,
    achsTex: achsRow.material.map,
    circTex: circRow.material.map,
    doorTex: door.material.map,
    champRow,
    insigniaCache: {},   // id → Texture | false (sin PNG) | null (cargando)
    lights,
  };
  return g;
}

export function createChampRoom(game) {
  let builtFor = null;        // activeId del set construido ('' = sala limpia)
  let set = null;             // { cfg, texs, disposables }
  let variantTint = 0xffffff; // teñido multiplicativo de la variante activa
  const loader = new THREE.TextureLoader();
  let maxAniso = 4;
  try { maxAniso = game.renderer.capabilities.getMaxAnisotropy(); } catch { /* */ }
  const WALL_MAP = ['left', 'right', 'back', 'front'];   // = orden de wallMats
  const KEYS = ['floor', 'ceil', 'left', 'right', 'back', 'front'];

  const ud = () => (game.roomGroup ? game.roomGroup.userData : null);

  /** Quita mapas y colores forzados y re-aplica el tema del jugador. */
  function clearRoom() {
    const U = ud();
    if (U) {
      const mats = [];
      if (U.floorMat) mats.push(U.floorMat);
      if (U.ceilMat) mats.push(U.ceilMat);
      if (U.wallMats) mats.push(...U.wallMats);
      for (const m of mats) {
        if (m && m.map) { m.map = null; m.needsUpdate = true; }
      }
    }
    variantTint = 0xffffff;
    if (U) { try { game.applyTheme(game.theme); } catch { /* */ } }
  }

  function disposeSet() {
    clearRoom();
    if (set) for (const d of set.disposables) { try { d.dispose(); } catch { /* */ } }
    set = null;
  }

  /** Construye (con carga perezosa) el decorado del campeonato «id». */
  function buildFor(id) {
    disposeSet();
    builtFor = id;
    const mod = id ? game.champs.moduleIfLoaded(id) : null;
    const cfg = (mod && mod.room) ? mod.room : null;
    if (!cfg) return;                        // campeonato sin «room»: sala clásica
    const base = 'championships/' + id + '/';
    const mine = { cfg, texs: {}, disposables: [] };
    set = mine;
    for (const key of KEYS) {
      const file = cfg[key];
      if (!file) continue;
      loader.load(base + file, (tex) => {
        if (set !== mine) { try { tex.dispose(); } catch { /* */ } return; }  // set ya sustituido
        try {
          tex.colorSpace = THREE.SRGBColorSpace;
          tex.anisotropy = maxAniso;
          mine.texs[key] = tex;
          mine.disposables.push(tex);
        } catch { /* el decorado NUNCA rompe el juego */ }
      }, undefined, () => { /* file:// o arte ausente: ese plano queda con su color */ });
    }
  }

  /** Mood por etapa (módulo): teñido multiplicativo + arte alternativo. */
  function useVariant(key) {
    let tint = 0xffffff;
    try {
      const v = (set && set.cfg && set.cfg.variants && set.cfg.variants[key]) || null;
      if (v && v.tint) tint = v.tint;
    } catch { /* */ }
    variantTint = tint;
  }

  /** Refuerzo por frame (barato e idempotente): mapas + blanco/tinte + */
  /** complementos de la sala clásica ocultos mientras haya arte.        */
  function update() {
    const activeId = (game.champs && game.champs.activeId) || '';
    if (activeId !== builtFor) buildFor(activeId);
    const U = ud();
    if (!U) return;
    const has = (k) => !!(set && set.texs[k]);
    if (set && Object.keys(set.texs).length) {
      const tint = variantTint;
      if (U.floorMat) {
        if (has('floor') && U.floorMat.map !== set.texs.floor) {
          U.floorMat.map = set.texs.floor; U.floorMat.needsUpdate = true;
        }
        if (has('floor')) U.floorMat.color.set(tint);
      }
      if (U.ceilMat) {
        if (has('ceil') && U.ceilMat.map !== set.texs.ceil) {
          U.ceilMat.map = set.texs.ceil; U.ceilMat.needsUpdate = true;
        }
        if (has('ceil')) U.ceilMat.color.set(tint);
      }
      const wm = U.wallMats || [];
      for (let i = 0; i < wm.length && i < 4; i++) {
        const m = wm[i];
        if (!m) continue;
        const t2 = set.texs[WALL_MAP[i]];
        if (t2 && m.map !== t2) { m.map = t2; m.needsUpdate = true; }
        if (t2) m.color.set(tint);
      }
      // complementos del núcleo que chocarían con el arte:
      if (U.grid) U.grid.visible = !has('floor');
      if (U.panels) for (const p of U.panels) p.visible = !has('ceil');
      if (U.strips) for (const s of U.strips) s.visible = !(has('left') || has('right'));
    } else {
      // sin decorado: la sala clásica queda EXACTAMENTE como siempre
      if (U.grid) U.grid.visible = true;
      if (U.panels) for (const p of U.panels) p.visible = true;
      if (U.strips) for (const s of U.strips) s.visible = true;
    }
  }

  return {
    /** Campeonato del decorado construido ('' = sala sin arte). */
    get builtFor() { return builtFor || ''; },
    /** Claves de arte ya cargadas del set activo (lectura en tests). */
    get loadedKeys() { return set ? Object.keys(set.texs) : []; },
    useVariant,
    update,
  };
}

export function createBounceMarkers() {
  const pool = [];
  for (let i = 0; i < 4; i++) {
    const m = new THREE.Mesh(
      new THREE.RingGeometry(0.02, 0.036, 20),
      new THREE.MeshBasicMaterial({
        color: 0xffffff, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide,
      }),
    );
    m.rotation.x = -Math.PI / 2;
    m.userData.t = 1;
    m.visible = false;
    m.renderOrder = 3;
    pool.push(m);
  }
  return pool;
}

export function createScoreboard() {
  const group = new THREE.Group();
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;

  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(1.7, 0.85),
    new THREE.MeshBasicMaterial({ map: tex }),
  );
  const frame = new THREE.Mesh(
    new THREE.BoxGeometry(1.76, 0.91, 0.04),
    new THREE.MeshStandardMaterial({ color: 0x101316, roughness: 0.6 }),
  );
  frame.position.z = -0.025;
  group.add(frame);
  group.add(panel);
  group.position.set(0, 1.95, DIMS.roomFrontZ + 0.9);

  let last = '';
  const update = (d) => {
    const key = d.mode === 'survival'
      ? `S|${d.rally}|${d.rallyes}|${d.best}|${d.server}|${d.message}`
      : `${d.player}|${d.ai}|${d.server}|${d.message}`;
    if (key === last) return;
    last = key;

    ctx.fillStyle = '#101418';
    ctx.fillRect(0, 0, 1024, 512);
    ctx.strokeStyle = '#2a3138';
    ctx.lineWidth = 10;
    ctx.strokeRect(10, 10, 1004, 492);

    ctx.textAlign = 'center';

    if (d.mode === 'survival') {
      // ---------- MODO SUPERVIVENCIA ----------
      ctx.fillStyle = '#e8b45a';
      ctx.font = '700 40px system-ui, sans-serif';
      ctx.fillText(T('sb_surv'), 512, 78);

      ctx.fillStyle = '#f2f4f6';
      ctx.font = '800 210px system-ui, sans-serif';
      ctx.fillText(String(d.rally || 0), 512, 315);

      ctx.fillStyle = '#c8ced4';
      ctx.font = '600 44px system-ui, sans-serif';
      ctx.fillText(T('sb_rally_hits'), 512, 390);

      ctx.fillStyle = '#8b949c';
      ctx.font = '500 40px system-ui, sans-serif';
      ctx.fillText(T('sb_rallies', { r: d.rallyes || 0, b: d.best || 0 }), 512, 452);
      tex.needsUpdate = true;
      return;
    }

    // v2.34: en ARCADE el cabecero del marcador pasa a ser el campeonato
    ctx.fillStyle = '#8b949c';
    ctx.font = '600 34px system-ui, sans-serif';
    ctx.fillText(d.oppLabel === 'clown'
      ? T('arc_title').split('').join(' ')
      : 'P I N G   P O N G   X R', 512, 70);

    ctx.textAlign = 'left';
    ctx.fillStyle = '#e8b45a';
    ctx.font = '700 52px system-ui, sans-serif';
    ctx.fillText(T('sb_you'), 150, 170);
    if (d.server === 'player') {
      ctx.beginPath();
      ctx.arc(118, 152, 13, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.textAlign = 'right';
    ctx.fillStyle = '#7fb069';
    ctx.font = '700 52px system-ui, sans-serif';
    // v2.27: RIVAL en online (antes decía CPU siempre); v2.34: CLOWN en arcade
    ctx.fillText(d.oppLabel === 'clown'
      ? T('sb_clown')
      : T(d.oppLabel === 'rival' ? 'sb_rival' : 'sb_cpu'), 874, 170);
    if (d.server === 'ai') {
      ctx.beginPath();
      ctx.arc(906, 152, 13, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.textAlign = 'center';
    ctx.fillStyle = '#f2f4f6';
    ctx.font = '800 190px system-ui, sans-serif';
    ctx.fillText(`${d.player} : ${d.ai}`, 512, 340);

    ctx.fillStyle = '#c8ced4';
    // v2.18: el mensaje se auto-ajusta (fuente menor) en vez de recortarse a
    // ciegas: en el visor los textos largos se salían del marco del panel.
    let msg = d.message || '';
    if (msg.length > 72) msg = msg.slice(0, 71) + '…';
    let msgFs = 40;
    ctx.font = `500 ${msgFs}px system-ui, sans-serif`;
    while (msgFs > 22 && ctx.measureText(msg).width > 920) {
      msgFs -= 2;
      ctx.font = `500 ${msgFs}px system-ui, sans-serif`;
    }
    ctx.fillText(msg, 512, 440);

    tex.needsUpdate = true;
  };

  update({ player: 0, ai: 0, server: 'player', message: '', mode: 'match', rally: 0, rallyes: 0, best: 0 });
  return { group, update };
}

/* =====================================================================
 *  PANEL DE AJUSTE DE PALA (modo entrenamiento en VR)
 *  Texto dinámico en CanvasTexture: nombre del agarre, valores actuales
 *  y controles. Solo se redibuja cuando cambian los valores.
 * ===================================================================== */
function roundRectPath(g, x, y, w, h, r) {
  g.beginPath();
  g.moveTo(x + r, y);
  g.arcTo(x + w, y, x + w, y + h, r);
  g.arcTo(x + w, y + h, x, y + h, r);
  g.arcTo(x, y + h, x, y, r);
  g.arcTo(x, y, x + w, y, r);
  g.closePath();
}

export function createCalibPanel() {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const g2 = canvas.getContext('2d');
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  const mat = new THREE.MeshBasicMaterial({
    map: tex, transparent: true, opacity: 0.95, side: THREE.DoubleSide, depthWrite: false,
  });
  const group = new THREE.Group();
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(0.46, 0.46), mat);
  group.add(plane);

  function update(d) {
    g2.clearRect(0, 0, 512, 512);
    g2.fillStyle = 'rgba(13,17,23,0.93)';
    g2.strokeStyle = 'rgba(232,180,90,0.85)';
    g2.lineWidth = 4;
    roundRectPath(g2, 8, 8, 496, 496, 24);
    g2.fill();
    g2.stroke();

    g2.textAlign = 'left';
    g2.fillStyle = '#e8b45a';
    g2.font = 'bold 40px system-ui, sans-serif';
    g2.fillText('AJUSTE DE PALA', 34, 66);
    g2.fillStyle = '#9aa7b4';
    g2.font = '24px system-ui, sans-serif';
    g2.fillText('Agarre: ' + d.name, 34, 104);

    const o = d.off;
    const deg = (r) => ((r * 180) / Math.PI).toFixed(0);
    const mm = (m) => Math.round(m * 1000);
    g2.fillStyle = '#cfd8e0';
    g2.font = '21px ui-monospace, monospace';
    g2.fillText(`pos  ${mm(o.px)} · ${mm(o.py)} · ${mm(o.pz)} mm`, 34, 146);
    g2.fillText(`gir  ${deg(o.rx)}° · ${deg(o.ry)}° · ${deg(o.rz)}°`, 34, 176);

    const lines = [
      ['STICK D', 'girar / inclinar la cara'],
      ['GRIP D + stick D', 'rodar la pala'],
      ['STICK I', 'mover la pala'],
      ['GRIP I + stick I', 'acercar / alejar'],
      ['A', 'guardar este agarre'],
      ['B', 'cargar el siguiente'],
      ['X', 'volver al agarre natural'],
      ['GATILLO', 'lanzar bola de entrenamiento'],
      ['Y', 'volver al entrenamiento'],
      ['B (en juego)', 'abrir / cerrar el MENÚ'],
      ['MENÚ', 'modo · dificultad · sala · ambiente'],
    ];
    // v2.18: re-espaciado — con paso 29 la última línea caía en y=514 (fuera
    // del canvas de 512 px) y el texto se salía del panel lateral.
    let y = 214;
    for (const [k, v] of lines) {
      g2.fillStyle = '#e8b45a';
      g2.font = 'bold 20px system-ui, sans-serif';
      g2.fillText(k, 34, y);
      g2.fillStyle = '#aeb9c5';
      g2.font = '20px system-ui, sans-serif';
      g2.fillText(v, 196, y);
      y += 25;
    }
    tex.needsUpdate = true;
  }

  return { group, update };
}

/* =====================================================================
 *  FANFARRIA DE FIN DE PARTIDO · cartel 3D flotante sobre la red con el
 *  ARTE OFICIAL del juego (v2.26: imágenes ¡HAS GANADO! / ¡HAS PERDIDO!;
 *  v2.27: versión por idioma — castellano e inglés incrustados en base64)
 *  + chip con el marcador final y la revancha. Lluvia de confeti 3D cuando
 *  se gana. Se muestra en todo el estado 'over'. Si la imagen aún no está
 *  decodificada (primer instante) se dibuja un panel de respaldo con el
 *  mismo texto; al cargar se repinta sola.
 * ===================================================================== */
const POSTER_SRC = {
  es: { win: 'data:image/webp;base64,', lose: 'data:image/webp;base64,' },
  en: { win: 'data:image/webp;base64,', lose: 'data:image/webp;base64,' },
};
export function createFanfareBanner() {
  // v2.44: carteles CUADRADOS (1024x1024) — victoria/derrota (ES) y
  // victory/lost (EN), arte WebP con alfa incrustado por build
  const W = 1024, H = 1024;
  const group = new THREE.Group();
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(1.18, 1.18),
    // FrontSide: de detrás se ve transparente (en la órbita de la demo) en
    // lugar del arte en espejo; en VR el jugador siempre está de frente.
    new THREE.MeshBasicMaterial({
      map: tex, transparent: true, side: THREE.FrontSide, depthWrite: false,
    }),
  );
  group.add(mesh);
  group.position.set(0, 1.86, DIMS.tableCenterZ);
  group.visible = false;
  group.renderOrder = 5;

  // v2.27: carteles por IDIOMA (carga diferida; cadena vacía = sin arte:
  // se usa el panel de respaldo dibujado en el canvas).
  const posters = {};
  let lastArgs = null;
  const ensurePoster = (lang, key) => {
    if (posters[key + ':' + lang] !== undefined) return;
    const url = (POSTER_SRC[lang] || POSTER_SRC.es)[key] || '';
    posters[key + ':' + lang] = null;         // marcado: en curso/sin arte
    if (!url) return;
    const img = new Image();
    img.onload = () => {
      posters[key + ':' + lang] = img;
      if (group.visible && lastArgs) draw(...lastArgs);   // repinta si está en pantalla
    };
    img.src = url;
  };

  function draw(win, pScore, aScore) {
    lastArgs = [win, pScore, aScore];
    const lang = (typeof TLang === 'function') ? TLang() : 'es';
    const key = win ? 'win' : 'lose';
    ensurePoster(lang, key);
    ctx.clearRect(0, 0, W, H);
    const img = posters[key + ':' + lang];
    if (img) {
      // cartel oficial a sangre completa (mismo aspecto: sin deformar ni recortar)
      ctx.drawImage(img, 0, 0, W, H);
    } else {
      // respaldo (imagen aún decodificando o arte ausente): panel con el mismo mensaje
      ctx.fillStyle = win ? 'rgba(43,26,4,0.94)' : 'rgba(12,16,22,0.94)';
      ctx.strokeStyle = win ? '#ffd35c' : '#ff5b4d';
      ctx.lineWidth = 14;
      roundRectPath(ctx, 14, 14, W - 28, H - 28, 40);
      ctx.fill();
      ctx.stroke();
      ctx.textAlign = 'center';
      ctx.shadowColor = win ? 'rgba(255,196,40,0.9)' : 'rgba(0,0,0,0.8)';
      ctx.shadowBlur = 26;
      ctx.fillStyle = win ? '#ffd35c' : '#ff6a5b';
      ctx.font = '900 128px system-ui, sans-serif';
      ctx.fillText(T(win ? 'fanf_win' : 'fanf_lose'), W / 2, H / 2 - 40);
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#f2f4f6';
      ctx.font = '800 78px system-ui, sans-serif';
      ctx.fillText(`${pScore} - ${aScore}`, W / 2, H / 2 + 90);
    }

    // chip inferior con el marcador final y la revancha (legible sobre el arte)
    const txt = T('fanf_chip', { p: pScore, q: aScore });
    ctx.font = '800 44px system-ui, sans-serif';
    const tw = ctx.measureText(txt).width;
    const cw = tw + 56, ch = 72;
    const cx = W / 2, cy = H - 58;
    ctx.fillStyle = win ? 'rgba(12,20,34,0.82)' : 'rgba(8,10,16,0.82)';
    ctx.strokeStyle = win ? 'rgba(255,211,92,0.9)' : 'rgba(255,107,91,0.9)';
    ctx.lineWidth = 5;
    roundRectPath(ctx, cx - cw / 2, cy - ch / 2, cw, ch, 36);
    ctx.fill();
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#ffffff';
    ctx.fillText(txt, cx, cy + 2);
    ctx.textBaseline = 'alphabetic';

    tex.needsUpdate = true;
  }

  // v2.27: al cambiar el idioma con el cartel en pantalla se repinta en el idioma nuevo
  function langChanged() {
    if (group.visible && lastArgs) draw(...lastArgs);
  }

  // canvas expuesto SOLO lectura (diagnóstico/verificación headless)
  return { group, draw, canvas, langChanged };
}

export function createConfetti() {
  // v2.35: lluvia MUCHO más densa (120 -> 430) y repartida también sobre
  // tu campo, para que el confeti del Clown estorbe la visión y el golpeo.
  const N = 430;
  const pos = new Float32Array(N * 3);
  const col = new Float32Array(N * 3);
  const fall = new Float32Array(N);
  const sway = new Float32Array(N);
  const phase = new Float32Array(N);
  const palette = [
    [1.0, 0.83, 0.36], [1.0, 0.42, 0.34], [0.34, 0.78, 1.0],
    [0.48, 0.88, 0.48], [0.9, 0.48, 0.88], [1.0, 1.0, 1.0],
  ];
  const topY = 2.45;
  const floorY = 0.85;
  // banda z: media mesa rival + TODA tu zona (el jugador está en z>0)
  const zMin = DIMS.tableCenterZ - 1.0;
  const zSpan = 3.2;   // hasta z≈+0,6: delante de tu cara, estorba el golpeo
  const reset = (i, first) => {
    pos[i * 3] = (Math.random() * 2 - 1) * 1.05;
    pos[i * 3 + 1] = first ? floorY + Math.random() * (topY - floorY) : topY;
    pos[i * 3 + 2] = zMin + Math.random() * zSpan;
    fall[i] = 0.32 + Math.random() * 0.42;   // caída lenta: queda más tiempo
    sway[i] = 0.12 + Math.random() * 0.2;
    phase[i] = Math.random() * Math.PI * 2;
    const c = palette[(Math.random() * palette.length) | 0];
    col[i * 3] = c[0]; col[i * 3 + 1] = c[1]; col[i * 3 + 2] = c[2];
  };
  for (let i = 0; i < N; i++) reset(i, true);

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  const points = new THREE.Points(geo, new THREE.PointsMaterial({
    size: 0.036, vertexColors: true, transparent: true, opacity: 0.95, depthWrite: false,
  }));
  points.visible = false;
  points.renderOrder = 6;

  let t = 0;
  const update = (dt, active) => {
    if (!active) { points.visible = false; return; }
    points.visible = true;
    t += dt;
    for (let i = 0; i < N; i++) {
      pos[i * 3 + 1] -= fall[i] * dt;
      pos[i * 3] += Math.sin(t * 2.4 + phase[i]) * sway[i] * dt;
      pos[i * 3 + 2] += Math.cos(t * 1.8 + phase[i]) * sway[i] * dt * 0.6;
      if (pos[i * 3 + 1] < floorY) reset(i, false);
    }
    geo.attributes.position.needsUpdate = true;
  };

  return { points, update };
}

/* =====================================================================
 *  MULTIJUGADOR ONLINE (v2.19) · P2P WebRTC vía PeerJS (sin servidor propio)
 *  - El anfitrión crea una sala con código de 5 caracteres (id ppxr3-CODE).
 *  - El invitado introduce el código con un teclado dibujado en el menú.
 *  - Canal de datos: poses de pala (20 Hz), estado de la bola (el dueño la
 *    simula y la emite), eventos de física y estado del partido.
 *  - VOZ: llamada de medios WebRTC entre ambos (micrófono del navegador).
 *    v2.25: la LLAMA el INVITADO al ID de la sala (el anfitrión responde).
 *    Antes llamaba el anfitrión a su PROPIO id: bucle hacia sí mismo y el
 *    rival sin voz. El micrófono se pide al crear/unirse (gesto 2D del menú,
 *    fuera de VR): el cambio de ruta de audio de Android ocurre ANTES de la
 *    sesión inmersiva y el WebAudio del juego no se queda mudo.
 *  Autoridad: el ANFITRIÓN lleva las reglas y el marcador; el invitado
 *  recibe el estado (reglas sombra). Marco de coordenadas:
 *  · EMISIÓN en CRUDO (posiciones locales tal cual) y RECEPCIÓN con UNA
 *    rotación de 180° en Y alrededor del centro de la mesa: (x,z)->(-x,-3.2-z).
 *    v2.25: ANTES se transformaba al emitir Y también al recibir — doble
 *    espejo: el rival aparecía en TU mismo lado y las bolas eran fantasmas.
 *    La involución aplicada UNA vez es el cambio de marco correcto (ambos
 *    mundos son copias idénticas que se miran de frente).
 *  · SINCRONÍA POR PUNTO DE VISTA: el anfitrión etiqueta los datos desde SU
 *    perspectiva ('player'=anfitrión). En el invitado 'player' soy YO, así
 *    que applySync intercambia marcador y sacador, remapea las causas de los
 *    puntos y genera megafonía local (antes el invitado callaba y veía el
 *    marcador invertido).
 * ===================================================================== */
